def flatten(obj, prefix=""):
    out = {}
    if isinstance(obj, dict):
        for k, v in obj.items(): out.update(flatten(v, f"{prefix}{k}."))
    elif isinstance(obj, list):
        for v in obj[:1]: out.update(flatten(v, prefix))
    else: out[prefix[:-1]] = type(obj).__name__
    return out
rec = {"author": {"name": "JAH", "id": 7}, "tags": ["a"]}
print(flatten(rec))
assert flatten(rec) == {"author.name": "str", "author.id": "int", "tags": "str"}

from collections import deque
links = {"home": ["a", "b"], "a": ["c"], "b": ["c"], "c": []}
seen, depth, q = {"home"}, {"home": 0}, deque(["home"])
order = []
while q:
    page = q.popleft(); order.append((page, depth[page]))
    for nxt in links[page]:
        if nxt not in seen:
            seen.add(nxt); depth[nxt] = depth[page] + 1; q.append(nxt)
print("crawl order:", order)
assert [d for _, d in order] == [0, 1, 1, 2]

sitemap = {"index": ["s1", "s2"], "s1": ["u1", "u2"], "s2": ["u3"]}
found = []
def walk(node):
    for child in sitemap.get(node, []):
        if child in sitemap: walk(child)
        else: found.append(child)
walk("index")
print("declared urls:", found)
assert found == ["u1", "u2", "u3"]

depth = {"home": 0, "/docs/a": 1, "/docs/b": 2, "/docs/b/c": 3, "/old/x": 4}
from collections import defaultdict
by_section = defaultdict(list)
for url, d in depth.items():
    by_section[url.split("/")[1] if "/" in url[1:] else "root"].append(d)
buried = {s: max(ds) for s, ds in by_section.items() if max(ds) >= 3}
print("buried sections:", buried)
assert "old" in buried

